"""Private Redis7.2 process over a Unix socket; no network, package or image changes."""
import pathlib,secrets,socket,subprocess,tempfile,time


class RedisError(Exception):pass


class Client:
    def __init__(self,path):
        self.socket=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM)
        self.socket.settimeout(3);self.socket.connect(str(path));self.stream=self.socket.makefile('rb');self.closed=False
    def command(self,*parts):
        values=[part if isinstance(part,bytes) else str(part).encode() for part in parts]
        self.socket.sendall(('*'+str(len(values))+'\r\n').encode()+b''.join(('$'+str(len(value))+'\r\n').encode()+value+b'\r\n' for value in values))
        return self.read()
    def read(self):
        line=self.stream.readline()
        if not line:raise ConnectionError('native Redis closed the connection')
        kind,value=line[:1],line[1:-2]
        if kind==b'+':return value.decode()
        if kind==b'-':raise RedisError(value.decode())
        if kind==b':':return int(value)
        if kind==b'$':
            size=int(value)
            if size<0:return None
            body=self.stream.read(size)
            if len(body)!=size or self.stream.read(2)!=b'\r\n':raise ConnectionError('short RESP payload')
            return body.decode('utf8')
        if kind==b'*':
            size=int(value)
            return None if size<0 else [self.read() for _ in range(size)]
        raise RuntimeError('unexpected RESP type')
    def close(self):
        if not self.closed:self.closed=True;self.stream.close();self.socket.close()


class NativeRedis:
    def __enter__(self):
        self.temp=tempfile.TemporaryDirectory(prefix='of-r2-');self.root=pathlib.Path(self.temp.name)
        self.path=self.root/'redis.sock';self.config=self.root/'redis.conf';self.proc=None;self.admin=None
        self.config.write_text('port 0\nunixsocket '+str(self.path)+'\nunixsocketperm 700\ndir '+str(self.root)+
            '\nsave ""\nappendonly no\ndbfilename snapshot.rdb\nlogfile '+str(self.root/'redis.log')+'\nloglevel warning\n',encoding='utf8')
        try:self.start();return self
        except BaseException:self.__exit__(None,None,None);raise
    def start(self):
        self.proc=subprocess.Popen(['redis-server',str(self.config)],stdout=subprocess.DEVNULL,stderr=subprocess.STDOUT)
        for _ in range(250):
            if self.proc.poll() is not None:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: private Redis exited during startup')
            if self.path.exists():
                try:
                    admin=Client(self.path)
                    if admin.command('PING')=='PONG':self.admin=admin;break
                    admin.close()
                except (OSError,ConnectionError):pass
            time.sleep(.01)
        if self.admin is None:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: private Redis startup deadline')
        version=dict(line.split(':',1) for line in self.admin.command('INFO','server').splitlines() if ':' in line)['redis_version']
        if not version.startswith('7.2.'):raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: Redis7.2 required')
        print('NATIVE_REDIS_READY:'+version,flush=True)
    def command(self,*args):return self.admin.command(*args)
    def client(self,user=None,password=None):
        client=Client(self.path)
        try:
            if user is not None:client.command('AUTH',user,password)
            return client
        except BaseException:client.close();raise
    def stop(self):
        if self.admin is not None:self.admin.close();self.admin=None
        if self.proc is not None:
            if self.proc.poll() is None:
                self.proc.terminate()
                try:self.proc.wait(timeout=4)
                except subprocess.TimeoutExpired:self.proc.kill();self.proc.wait(timeout=3)
            self.proc=None
    def __exit__(self,*args):
        try:self.stop()
        finally:self.temp.cleanup()


def student(function,*args):
    print('STUDENT_OPERATION_ENTERED:'+function.__name__,flush=True)
    try:return function(*args)
    except Exception as error:raise AssertionError('student operation failed: '+type(error).__name__) from error


def token(prefix='x'):return prefix+'_'+secrets.token_hex(8)


def acl_profile(command,user):
    value=command('ACL','GETUSER',user)
    return None if value is None else dict(zip(value[::2],value[1::2]))

